function currentRoute(){return(location.hash.replace(/^#\/?/,'').split(/[?&]/)[0]||'home').toLowerCase()}
function setView(route){const authenticated=Boolean(state.session);document.body.classList.toggle('app-mode',authenticated&&pages.includes(route));document.body.classList.toggle('auth-mode',route==='auth'||route==='login'||route==='register');$('landingView').classList.toggle('hidden',route!=='home');$('authView').classList.toggle('hidden',!['auth','login','register'].includes(route));$('tutorialView').classList.toggle('hidden',route!=='tutorial');$('appView').classList.toggle('hidden',!(authenticated&&pages.includes(route)));document.querySelectorAll('[data-private]').forEach(node=>node.classList.toggle('hidden',!authenticated));if(['auth','login','register'].includes(route))setAuthTab(route==='register'?'register':'login')}
async function route(){stopTimers();let route=currentRoute();if(!state.session&&pages.includes(route)){location.hash='auth';return}if(state.session&&['home','auth','login','register'].includes(route)){route='dashboard';if(location.hash!=='#dashboard')history.replaceState(null,'','#dashboard')}if(['owner','main-console','agent-owner'].includes(route)&&!hasRole('owner'))route='dashboard';if(!['home','auth','login','register','tutorial',...pages].includes(route))route=state.session?'dashboard':'home';setView(route);if(!pages.includes(route))return;pages.forEach(name=>$(name+'Page').classList.toggle('hidden',name!==route));$('pageTitle').textContent=route==='owner'?'OWNER PANEL':route==='wallet'?'SALDO UMI':route==='main-console'?'CONSOLE BOT UTAMA':route==='chat'?'CHAT GLOBAL':route==='feedback'?'FEEDBACK':route.toUpperCase();$('newSessionButton').classList.toggle('hidden',!['dashboard','connect'].includes(route));$('mainNav').classList.remove('open');$('menuToggle').setAttribute('aria-expanded','false');try{if(route==='dashboard')await loadSessions();if(route==='wallet')await openWallet();if(route==='settings')await openSettings();if(route==='feedback')await openFeedback();if(route==='chat')await openChat();if(route==='plugins')await openPlugins();if(route==='console')await openConsole();if(route==='main-console')await openMainConsole();if(route==='owner')await loadOwner();if(route==='agent')await loadAgent();if(route==='agent-owner')await loadOwnerAgent()}catch(error){toast(error.message,true)}}
function setAuthTab(tab){document.querySelectorAll('[data-auth-tab]').forEach(button=>button.classList.toggle('active',button.dataset.authTab===tab));$('loginForm').classList.toggle('hidden',tab!=='login');$('registerForm').classList.toggle('hidden',tab!=='register')}
function sessionOptions(select,placeholder='Pilih session'){const selected=select.value||state.selected;select.innerHTML=`<option value="">${placeholder}</option>`+state.sessions.map(item=>`<option value="${escapeHtml(item.sessionId)}">+${escapeHtml(item.sessionId)} · ${escapeHtml(item.status||'unknown')}</option>`).join('');if([...select.options].some(option=>option.value===String(selected)))select.value=String(selected)}
async function loadSessions(){const data=await api('sessions');state.sessions=Array.isArray(data.sessions)?data.sessions:[];$('statTotal').textContent=state.sessions.length;$('statOnline').textContent=state.sessions.filter(item=>item.status==='connected').length;$('statOffline').textContent=state.sessions.filter(item=>item.status!=='connected').length;renderSessions();return state.sessions}
function renderSessions(){const list=$('sessionList');if(!state.sessions.length){list.innerHTML='<article class="panel"><h3>BELUM ADA BOT</h3><p>Buat session pertama dengan nomor WhatsApp milikmu.</p><button class="btn btn-primary" data-action="new">PAIRING SEKARANG</button></article>';return}list.innerHTML=state.sessions.map(item=>{const status=['connected','pending','disconnected'].includes(item.status)?item.status:'disconnected';return`<article class="session-card"><div class="phone">+${escapeHtml(item.sessionId)}</div><span class="badge ${status}">${escapeHtml(String(item.status||'unknown').toUpperCase())}</span><p>${item.registered?'WhatsApp terdaftar dan siap dipakai.':'Selesaikan pairing untuk mengaktifkan bot.'}</p><div class="actions"><button class="mini" data-action="settings" data-id="${escapeHtml(item.sessionId)}">SETTINGS</button><button class="mini" data-action="restart" data-id="${escapeHtml(item.sessionId)}">RESTART</button><button class="mini danger" data-action="remove" data-id="${escapeHtml(item.sessionId)}">HAPUS</button></div></article>`}).join('')}
function formatIdr(value){return new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(Number(value)||0)}
function safeHttpsHref(value){try{const url=new URL(String(value||''));return url.protocol==='https:'?url.href:'#'}catch{return'#'}}
function walletStatusClass(status){return['PAID','UNPAID','EXPIRED','FAILED','CREATING','CREATE_FAILED','WAITING_APPROVAL','REJECTED'].includes(String(status))?String(status):'UNKNOWN'}
function renderWallet(data={}){state.wallet=data;const enabled=data.enabled===true,manual=data.mode==='manual_dana';$('walletBalance').textContent=formatIdr(data.balance);$('walletChannel').textContent=escapeHtml(manual?'DANA MANUAL':data.channel||'DANA');$('walletState').textContent=enabled?'SIAP':'BELUM AKTIF';const input=$('walletTopupAmount'),button=$('walletTopupForm').querySelector('button');input.min=String(data.minimumTopupIdr||10000);input.max=String(data.maximumTopupIdr||5000000);if(Number(input.value)<Number(input.min))input.value=input.min;button.disabled=!enabled;button.textContent=manual?'KONFIRMASI SUDAH BAYAR':'BUAT INVOICE DANA';const notice=$('walletTopupNotice');if(!enabled){notice.textContent='Top up belum diaktifkan oleh owner.'}else if(manual){const qr=safeHttpsHref(data.manualPayment?.qrUrl);notice.innerHTML=`<b>DANA MANUAL</b><br>1. Scan QR DANA di bawah dan lakukan pembayaran sesuai nominal.<br>2. Setelah pembayaran berhasil, tekan <b>KONFIRMASI SUDAH BAYAR</b>.<br>3. Owner memeriksa mutasi DANA lalu menambahkan saldo.<br>${qr!=='#'?`<img src="${escapeHtml(qr)}" alt="QR pembayaran DANA" style="display:block;width:min(100%,320px);margin:14px auto 0;background:#fff;padding:8px">`:''}`}else{notice.textContent=`Top up ${formatIdr(data.minimumTopupIdr)}–${formatIdr(data.maximumTopupIdr)}. Saldo dikreditkan setelah callback DANA tervalidasi.`}const topups=Array.isArray(data.topups)?data.topups:[],ledger=Array.isArray(data.ledger)?data.ledger:[];const active=topups.find(item=>['CREATING','UNPAID','WAITING_APPROVAL'].includes(String(item.status)));const activeBox=$('walletActiveInvoice');if(active){if(manual){activeBox.innerHTML=`<b>MENUNGGU VERIFIKASI OWNER</b><br>Top up ${escapeHtml(formatIdr(active.amount))} dicatat pada ${escapeHtml(active.createdAt?new Date(active.createdAt).toLocaleString('id-ID'):'—')}. Saldo akan masuk setelah owner mengonfirmasi pembayaran DANA.`}else{const href=safeHttpsHref(active.checkoutUrl),link=href!=='#'?`<br><a class="btn btn-yellow" href="${escapeHtml(href)}" target="_blank" rel="noopener noreferrer">BAYAR INVOICE ↗</a>`:'';activeBox.innerHTML=`<b>INVOICE AKTIF · ${escapeHtml(walletStatusClass(active.status))}</b><br>${formatIdr(active.totalAmount||active.amount)} · ${escapeHtml(active.paymentName||data.channel||'DANA')} · berlaku sampai ${escapeHtml(active.expiresAt?new Date(active.expiresAt).toLocaleString('id-ID'):'—')}${link}`}activeBox.classList.remove('hidden')}else{activeBox.textContent='';activeBox.classList.add('hidden')}$('walletLedger').innerHTML=ledger.map(item=>`<div class="list-item"><span><b>${escapeHtml(item.type==='TOPUP'||item.type==='TOPUP_MANUAL'?'TOP UP':'PEMBELIAN PANEL')}</b><br><small>${escapeHtml(item.description||item.reference||'Transaksi Wallet')}</small></span><span><b>${item.amount>=0?'+':'−'}${escapeHtml(formatIdr(Math.abs(Number(item.amount)||0)))}</b><br><small>Saldo: ${escapeHtml(formatIdr(item.balanceAfter))}<br>${escapeHtml(item.createdAt?new Date(item.createdAt).toLocaleString('id-ID'):'—')}</small></span></div>`).join('')||'<p>Belum ada transaksi saldo.</p>';$('walletTopups').innerHTML=topups.map(item=>{const href=safeHttpsHref(item.checkoutUrl),link=!manual&&['UNPAID','CREATING'].includes(String(item.status))&&href!=='#'?`<a class="mini" href="${escapeHtml(href)}" target="_blank" rel="noopener noreferrer">BAYAR</a>`:'';return`<div class="list-item"><span><b>${escapeHtml(walletStatusClass(item.status))} · ${escapeHtml(formatIdr(item.totalAmount||item.amount))}</b><br><small>${escapeHtml(item.paymentName||data.channel||'DANA')} · Ref: ${escapeHtml(item.reference||item.merchantRef||'—')}<br>${escapeHtml(item.createdAt?new Date(item.createdAt).toLocaleString('id-ID'):'—')}</small></span>${link}</div>`}).join('')||'<p>Belum ada invoice top up.</p>'}

async function loadWallet(){const data=await api('wallet/status');renderWallet(data);return data}
async function openWallet(){await loadWallet();clearInterval(state.walletTimer);state.walletTimer=setInterval(()=>loadWallet().catch(()=>{}),10000)}
async function submitWalletTopup(event){event.preventDefault();const form=event.currentTarget,button=form.querySelector('button'),amount=Number(form.elements.amount.value);if(!Number.isInteger(amount))return toast('Nominal top up tidak valid.',true);busy(button,true,'MEMBUAT INVOICE…');try{const result=await post('wallet/topup',{amount});toast(state.wallet?.mode==='manual_dana'?'Permintaan top up dikirim. Menunggu verifikasi owner.':'Invoice DANA dibuat. Selesaikan pembayaran untuk menambah saldo.');await loadWallet();$('walletActiveInvoice').scrollIntoView({behavior:'smooth',block:'center'})}catch(error){toast(error.message,true)}finally{busy(button,false)}}
async function sessionAction(event){const button=event.target.closest('[data-action]');if(!button)return;const id=button.dataset.id;if(button.dataset.action==='new'){location.hash='connect';return}if(button.dataset.action==='settings'){state.selected=id;location.hash='settings';return}if(button.dataset.action==='restart'){busy(button,true);try{await post('session/restart',{session_id:id});toast('Restart dikirim.')}catch(error){toast(error.message,true)}finally{busy(button,false)}}if(button.dataset.action==='remove'&&confirm(`Hapus session +${id}?`)){busy(button,true);try{await post('session/logout',{session_id:id});toast('Session dihapus.');await loadSessions()}catch(error){toast(error.message,true)}finally{busy(button,false)}}}
async function requestPairing(event){event.preventDefault();const phone=$('pairPhone').value.replace(/\D/g,'');if(phone.length<8)return toast('Nomor WhatsApp tidak valid.',true);const button=event.currentTarget.querySelector('button');const copy=$('copyPairCode');$('pairCode').textContent='••••-••••';delete $('pairCode').dataset.code;copy.disabled=true;state.pairLogs=[];addPairLog('Meminta kode pairing dari server.');busy(button,true,'MEMINTA KODE...');try{const data=await post('session/pairing',{phone});const formatted=formatPairCode(data.code||data.pairingCode);$('pairCode').textContent=formatted.display;$('pairCode').dataset.code=formatted.code;copy.disabled=!formatted.code;$('pairStatus').textContent=data.message||'Kode dibuat. Masukkan di WhatsApp.';addPairLog(formatted.code?'Kode pairing diterima. Gunakan tombol Salin Code atau salin dari layar.':'Server belum mengirim kode pairing.');state.selected=phone;let lastStatus='';clearInterval(state.pairTimer);state.pairTimer=setInterval(async()=>{try{const status=await api(`session/status?session_id=${encodeURIComponent(phone)}`);const current=String(status.status||'pending');$('pairStatus').textContent=`Status: ${current}`;if(current!==lastStatus){lastStatus=current;addPairLog(`Status session: ${current}.`)}if(current==='connected'){clearInterval(state.pairTimer);addPairLog('WhatsApp berhasil terhubung.');toast('Bot berhasil terhubung.');location.hash='dashboard'}}catch{if(lastStatus!=='check_failed'){lastStatus='check_failed';addPairLog('Status session belum dapat diperiksa; mencoba lagi otomatis.')}}},4000)}catch(error){toast(error.message,true);$('pairStatus').textContent=error.message;addPairLog(`Pairing gagal: ${error.message||'kesalahan tidak diketahui'}.`)}finally{busy(button,false)}}
async function openSettings(){await loadSessions();if(!state.sessions.length){location.hash='connect';return}sessionOptions($('settingsSession'));if(!state.selected||!state.sessions.some(item=>String(item.sessionId)===String(state.selected)))state.selected=String(state.sessions[0].sessionId);$('settingsSession').value=state.selected;await loadSettings()}
async function loadSettings(){state.selected=$('settingsSession').value;if(!state.selected)return;const item=state.sessions.find(x=>String(x.sessionId)===String(state.selected));$('sessionStatus').textContent=item?`${String(item.status).toUpperCase()} · +${item.sessionId}`:'—';const data=await api(`settings/get?session_id=${encodeURIComponent(state.selected)}`),s=data.settings||{},f=$('settingsForm').elements;f.bot_name.value=s.bot_name||'';f.owner_number.value=s.owner_number||'';$('lockedOwnerNumber').value=s.locked_owner_number||'6287813709432';f.prefix.value=s.prefix||'.';f.mode.value=['self','private'].includes(s.mode)?'self':'public';f.only_group.checked=s.only_group===true;f.registration_required.checked=s.registration_required!==false;f.default_limit.value=s.default_limit??25;f.auto_typing.checked=s.auto_typing!==false;f.auto_translate.checked=s.auto_translate!==false;f.send_music.checked=s.tiktok?.sendMusic!==false;f.menu_audio_enabled.checked=s.menu_audio_enabled!==false;f.max_photos.value=s.tiktok?.maxPhotos||8;f.website_url.value=s.links?.websiteUrl||'';f.channel_url.value=s.links?.channelUrl||'';f.upch_channel_url.value=s.upch_channel?.url||'';f.group_url.value=s.links?.groupUrl||'';f.typing_min.value=s.auto_typing_config?.minDelayMs??s.autoTyping?.minDelayMs??0;f.typing_max.value=s.auto_typing_config?.maxDelayMs??s.autoTyping?.maxDelayMs??80;f.typing_cps.value=s.auto_typing_config?.charsPerSecond??s.autoTyping?.charsPerSecond??10000;f.translate_language.value=s.auto_translate_config?.defaultLanguage??s.autoTranslate?.defaultLanguage??'id';f.connect_timeout.value=s.runtime?.connectTimeoutMs??60000;f.keepalive.value=s.runtime?.keepAliveIntervalMs??30000;f.retry_delay.value=s.runtime?.retryRequestDelayMs??250;f.max_retries.value=s.runtime?.maxMessageRetries??5;f.multiplier.value=s.multiplier??38;f.wait_text.value=s.wait_text||'';f.error_text.value=s.error_text||'';f.disabled_plugins.value=(s.disabled_plugins||[]).join('\n');await loadBackups()}
async function saveSettings(event){event.preventDefault();if(!state.selected)return;const f=event.currentTarget.elements,links={};if(f.website_url.value.trim())links.websiteUrl=f.website_url.value.trim();if(f.channel_url.value.trim())links.channelUrl=f.channel_url.value.trim();if(f.group_url.value.trim())links.groupUrl=f.group_url.value.trim();const payload={session_id:state.selected,upch_channel_url:f.upch_channel_url.value.trim(),bot_name:f.bot_name.value.trim(),owner_number:f.owner_number.value.replace(/\D/g,''),prefix:f.prefix.value,mode:f.mode.value,only_group:f.only_group.checked,registration_required:f.registration_required.checked,default_limit:Number(f.default_limit.value),auto_typing:f.auto_typing.checked,auto_typing_config:{minDelayMs:Number(f.typing_min.value),maxDelayMs:Number(f.typing_max.value),charsPerSecond:Number(f.typing_cps.value),includeMedia:true},auto_translate:f.auto_translate.checked,auto_translate_config:{source:'id',defaultLanguage:f.translate_language.value.trim()||'id'},menu_audio_enabled:f.menu_audio_enabled.checked,runtime:{connectTimeoutMs:Number(f.connect_timeout.value),keepAliveIntervalMs:Number(f.keepalive.value),retryRequestDelayMs:Number(f.retry_delay.value),maxMessageRetries:Number(f.max_retries.value)},wait_text:f.wait_text.value,error_text:f.error_text.value,multiplier:Number(f.multiplier.value),tiktok:{sendMusic:f.send_music.checked,maxPhotos:Number(f.max_photos.value)},links,disabled_plugins:f.disabled_plugins.value.split(/\n/).map(x=>x.trim()).filter(Boolean)};const button=event.currentTarget.querySelector('[type="submit"]');busy(button,true,'MENYIMPAN...');try{await post('settings/apply',payload);toast('Settings tersimpan dan diterapkan.')}catch(error){toast(error.message,true)}finally{busy(button,false)}}
async function loadBackups(){if(!state.selected)return;const data=await api(`backup/list?session_id=${encodeURIComponent(state.selected)}`);$('backupList').innerHTML=(data.backups||[]).map(item=>`<div class="list-item"><span><b>${escapeHtml(new Date(item.createdAt).toLocaleString('id-ID'))}</b><br><small>${escapeHtml(item.id)}</small></span><button class="mini" data-restore="${escapeHtml(item.id)}">RESTORE</button></div>`).join('')||'<p>Belum ada backup.</p>'}
